begin;

create unique index if not exists uq_exercises_legacy_shared
  on public.exercises (legacy_id) where student_id is null;
alter table public.theory_blocks drop constraint if exists theory_blocks_kind_check;
alter table public.theory_blocks add constraint theory_blocks_kind_check
  check (kind in ('prose', 'hero', 'cases', 'formula', 'traps', 'pairs'));

insert into public.topics (slug, title, description, position)
values ($g0$comparisons$g0$, $g1$Ступені порівняння (Comparisons)$g1$, $g2$Ступені порівняння прикметників і прислівників: comparative і superlative, as … as, подвійні форми, like / as, типові помилки.$g2$, 8)
on conflict (slug) do update set title = excluded.title,
