insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g3$th_hero$g3$, $g4$Ступені порівняння$g4$, $g5$elementary$g5$, $g6$hero$g6$, $g7${"title":"Comparisons","chips":["Англійська граматика","Ступені порівняння"],"lead":"Щоб порівняти двох, у прикметника й прислівника є <b>comparative</b> («швидший»), а щоб виділити одного з групи, — <b>superlative</b> («найшвидший»). Усе вирішує довжина слова.","diagramTitle":"Три ступені одного слова","diagram":[{"role":"звичайний","label":"cheap","tone":"neutral"},{"role":"порівняльний","label":"cheaper than","tone":"colour"},{"role":"найвищий","label":"the cheapest of","tone":"noun"}],"diagramNote":"base → comparative + than → the + superlative + of/in"}$g7$::jsonb, null, 0
from public.topics where slug = $g8$comparisons$g8$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g9$th_1$g9$, $g10$Два порівняння: than і the … of/in$g10$, $g11$elementary$g11$, $g12$formula$g12$, $g13${"step":"Двох чи багатьох","kicker":"Базове розуміння","lead":"У прикметника дві форми порівняння. <b>Comparative</b> порівнює двох, <b>superlative</b> виділяє одного з усієї групи.","tiles":[{"role":"двох між собою","label":"comparative + than","tone":"colour"},{"role":"один із групи","label":"the + superlative + of / in","tone":"noun"}],"legend":[{"tone":"colour","label":"Tina is shorter than Pam."},{"tone":"noun","label":"Peter is the smartest of all my students."}],"examples":[{"text":"Tina is <b>shorter than</b> Pam.","plain":"Tina is shorter than Pam.","note":"двох"},{"text":"This chair is <b>more comfortable than</b> the other one.","plain":"This chair is more comfortable than the other one.","note":"двох"},{"text":"Peter is <b>the smartest of</b> all my students.","plain":"Peter is the smartest of all my students.","note":"група людей"},{"text":"'Don's' is <b>the most expensive</b> restaurant <b>in</b> our town.","plain":"Don's is the most expensive restaurant in our town.","note":"in + місце"}],"note":"Після найвищого ступеня <b>in</b> вживаємо, коли йдеться про місце (<i>in our town, in the world</i>), а <b>of</b> — про групу (<i>of all, of the three</i>)."}$g13$::jsonb, null, 1
from public.topics where slug = $g14$comparisons$g14$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g15$th_2$g15$, $g16$Як утворити: -er / -est чи more / most$g16$, $g17$elementary$g17$, $g18$cases$g18$, $g19${"step":"-er чи more","kicker":"Усе залежить від довжини","lead":"Вибір форми залежить від кількості складів і закінчення прикметника.","cards":[{"icon":"1","title":"Один склад: -er / -est","text":"Додаємо <b>-er</b> і <b>-est</b>. Кілька слів абстрактного значення мають обидві форми: clear, safe, true, free, wise.","example":"soft · softer · softest","examplePlain":"soft, softer, softest"},{"icon":"y","title":"Два склади на -y: -ier / -iest","text":"Основна форма <b>-ier / -iest</b>. Форма з more / most теж можлива, але вживається рідше.","example":"easy · easier · easiest","examplePlain":"easy, easier, easiest"},{"icon":"2","title":"Два склади: на вибір","text":"Clever, common, stupid, narrow, gentle, friendly, simple беруть <b>або -er / -est, або more / most</b>.","example":"common · commoner · commonest<br>common · more common · most common","examplePlain":"common, commoner, commonest. Common, more common, most common."},{"icon":"▮","title":"-ing, -ed, -ful, -less: more / most","text":"Прикметники з цими закінченнями завжди беруть <b>more / most</b>.","example":"thrilling · more thrilling · most thrilling","examplePlain":"thrilling, more thrilling, most thrilling"},{"icon":"3+","title":"Три склади й більше: more / most","text":"Довгі прикметники ніколи не беруть -er / -est.","example":"intelligent · more intelligent · most intelligent","examplePlain":"intelligent, more intelligent, most intelligent"},{"icon":"≠","title":"Real, right, wrong","text":"Хоч вони односкладові, беруть лише <b>more / most</b>.","example":"real · more real · most real","examplePlain":"real, more real, most real"}],"axis":{"title":"Правило пальця","points":[{"label":"1 склад","text":"<b>-er / -est</b>"},{"label":"2 склади на -y","text":"<b>-ier / -iest</b>"},{"label":"3+ складів","text":"<b>more / most</b>"}]}}$g19$::jsonb, null, 2
