on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g21$th_3$g21$, $g22$Неправильні форми$g22$, $g23$intermediate$g23$, $g24$pairs$g24$, $g25${"step":"Неправильні","kicker":"Вивчити напам'ять","lead":"Кілька найуживаніших слів мають окремі форми. Вони однакові для прикметника й прислівника.","groups":[{"title":"Прикметник / прислівник","note":"comparative → superlative","items":[["good / well","better → best"],["bad / badly","worse → worst"],["much / many / a lot of","more → most"],["little","less → least"],["far","further (farther) → furthest (farthest)"]]}],"notes":["<b>further / farther</b> (прислівник) — далі за відстанню: <i>Barclays Bank is <b>further / farther</b> away than Lloyds.</i>","<b>further</b> (прикметник) = «додатковий», тут тільки <i>further</i>: <i>Let's hope there won't be any <b>further</b> delays.</i> (НЕ <s>farther delays</s>).","<b>elder / eldest</b> — лише перед іменником і про членів родини: <i>My <b>elder</b> brother is a doctor.</i> Але: <i>My brother is <b>older than</b> me.</i> (НЕ <s>elder than</s>)."]}$g25$::jsonb, null, 3
from public.topics where slug = $g26$comparisons$g26$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
