insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g27$th_4$g27$, $g28$Ступені прислівників$g28$, $g29$intermediate$g29$, $g30$formula$g30$, $g31${"step":"Прислівники","kicker":"Так само, як у прикметників","lead":"Прислівники порівнюються за тими самими правилами. Ключове питання: чи збігається прислівник із прикметником.","tiles":[{"role":"та сама форма, що в прикметника","label":"-er / -est","tone":"colour"},{"role":"прислівник на -ly","label":"more / most","tone":"noun"}],"legend":[{"tone":"colour","label":"hard → harder → hardest · late → later → latest"},{"tone":"noun","label":"comfortably → more comfortably → most comfortably"}],"examples":[{"text":"Dad works <b>hard</b>. Mike works <b>harder</b>.","plain":"Dad works hard. Mike works harder.","note":"hard — не hardly"},{"text":"She arrived <b>later</b> than usual.","plain":"She arrived later than usual.","note":"late"},{"text":"He spoke <b>more angrily</b> than usual.","plain":"He spoke more angrily than usual.","note":"-ly → more"}],"note":"<b>Hardly</b> — не «наполегливо», а «ледве». Наполегливо — <b>hard</b>."}$g31$::jsonb, null, 4
from public.topics where slug = $g32$comparisons$g32$
