insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g33$th_5$g33$, $g34$Підсилювачі: very, much, by far, any$g34$, $g35$intermediate$g35$, $g36$cases$g36$, $g37${"step":"Що стоїть поруч","kicker":"Слова, які підсилюють","lead":"Різні підсилювачі сполучаються з різними ступенями. Їх не можна міняти місцями.","cards":[{"icon":"1","title":"very + прикметник","text":"Лише зі звичайною формою.","example":"It's <b>very</b> cold today.","examplePlain":"It's very cold today."},{"icon":"2","title":"much, a lot, far, even + comparative","text":"Також a bit, a little, slightly. Зі звичайною формою й superlative не вживаються.","example":"He seems <b>much</b> better today.","examplePlain":"He seems much better today."},{"icon":"3","title":"by far + superlative","text":"«Набагато найкращий».","example":"She's <b>by far the most beautiful</b> woman I've ever seen.","examplePlain":"She's by far the most beautiful woman I've ever seen."},{"icon":"4","title":"most = very","text":"Перед прикметником або прислівником без the означає «дуже».","example":"This is <b>most</b> unusual.","examplePlain":"This is most unusual."},{"icon":"5","title":"any / no + comparative","text":"Any — у питаннях і запереченнях, no — у ствердженнях.","example":"The days aren't getting <b>any warmer</b>. / I want <b>no more</b> of that.","examplePlain":"The days aren't getting any warmer. I want no more of that."},{"icon":"6","title":"quite і rather","text":"Quite стоїть перед a, а <b>rather</b> підсилює comparative.","example":"He is <b>quite a</b> tall man. / It is <b>rather bigger</b> than the old one.","examplePlain":"He is quite a tall man. It is rather bigger than the old one."}]}$g37$::jsonb, null, 5
