insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g39$th_6$g39$, $g40$As … as і the same … as$g40$, $g41$elementary$g41$, $g42$cases$g42$, $g43${"step":"Однаково","kicker":"Коли обидва рівні","lead":"Щоб сказати, що двоє однакові (або ні), порівняння будуємо не через than.","cards":[{"icon":"=","title":"as + прикметник + as","text":"Однакові. Другий <b>as</b> обов'язковий.","example":"She is <b>as tall as</b> I am.","examplePlain":"She is as tall as I am."},{"icon":"≠","title":"not so / as + прикметник + as","text":"Не такий, як. Після not може стояти й so, й as.","example":"It is <b>not so/as hot as</b> it was yesterday.","examplePlain":"It is not so hot as it was yesterday."},{"icon":"≡","title":"the same … as","text":"Той самий. Після the same ставимо <b>as</b>, не than.","example":"Your dress is <b>the same</b> colour <b>as</b> mine.","examplePlain":"Your dress is the same colour as mine."}]}$g43$::jsonb, null, 6
