insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g45$th_7$g45$, $g46$Ще чотири типи порівнянь$g46$, $g47$intermediate$g47$, $g48$cases$g48$, $g49${"step":"Типи порівнянь","kicker":"Конструкції на вибір","lead":"Окрім than і as … as, порівняння будують ще чотирма способами.","cards":[{"icon":"×2","title":"twice / three times / half as … as","text":"Кратність. Не twice <s>more</s>.","example":"Their car was <b>twice as expensive as</b> ours.","examplePlain":"Their car was twice as expensive as ours."},{"icon":"−","title":"less … than · the least … of / in","text":"Зворотний бік comparative й superlative.","example":"The Park Hotel is <b>less expensive than</b> the Plaza. The King George is <b>the least expensive of</b> all.","examplePlain":"The Park Hotel is less expensive than the Plaza. The King George is the least expensive of all."},{"icon":"↗","title":"the + comparative, the + comparative","text":"Що більше, то більше. Обидві частини з the.","example":"<b>The earlier</b> we set off, <b>the earlier</b> we'll arrive.","examplePlain":"The earlier we set off, the earlier we'll arrive."},{"icon":"↑↑","title":"comparative and comparative","text":"Поступова зміна. Для довгих слів: more and more.","example":"The weather is getting <b>warmer and warmer</b>.","examplePlain":"The weather is getting warmer and warmer."}]}$g49$::jsonb, null, 7
