insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g51$th_8$g51$, $g52$Like чи as?$g52$, $g53$intermediate$g53$, $g54$cases$g54$, $g55${"step":"Like чи as","kicker":"Схожий чи «в ролі»","lead":"Like описує схожість, as називає роль. Решта випадків — окремі правила.","cards":[{"icon":"≈","title":"Like: схожість","text":"Зі словами, займенниками й -ing. Також після <b>feel, look, smell, sound, taste</b> + іменник.","example":"She swims <b>like</b> a fish. / It feels <b>like</b> silk.","examplePlain":"She swims like a fish. It feels like silk."},{"icon":"∼","title":"Like: подібність і протиставлення","text":"З іменниками, займенниками й -ing.","example":"There's no place <b>like</b> home. / No one can sing <b>like</b> him.","examplePlain":"There's no place like home. No one can sing like him."},{"icon":"◉","title":"As: роль","text":"Ким або чим є хтось насправді (професія, функція).","example":"She works <b>as</b> a tour guide.","examplePlain":"She works as a tour guide."},{"icon":"∞","title":"As: сталі вирази","text":"<b>as usual, as … as, as much, such as, the same as</b>.","example":"He started complaining <b>as</b> usual.","examplePlain":"He started complaining as usual."},{"icon":"⇢","title":"As: після певних дієслів","text":"<b>accept, be known, class, describe, refer to, regard, use</b> + as.","example":"He is known <b>as</b> the father of modern medicine.","examplePlain":"He is known as the father of modern medicine."},{"icon":"∷","title":"As: спосіб дії","text":"У підрядному реченні означає «так, як».","example":"Do <b>as</b> I tell you.","examplePlain":"Do as I tell you."}]}$g55$::jsonb, null, 8
from public.topics where slug = $g56$comparisons$g56$
