insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g57$th_9$g57$, $g58$Стоп-калька: помилки в порівняннях$g58$, $g59$elementary$g59$, $g60$traps$g60$, $g61${"step":"Стоп-калька 1","kicker":"Захист від рідної мови","lead":"Українські конструкції з «ніж», «на», «двічі» часто перекладаються дослівно. Ось типові збої.","items":[{"title":"«Вона вища за мене»","bad":"Pam is taller than I.","good":"Pam is taller than <b>me</b>. / …than <b>I am</b>.","goodPlain":"Pam is taller than me. Pam is taller than I am.","rule":"Після <i>than</i> — або <b>me</b>, або <b>I am</b>. Голе <i>I</i> вважається застарілим."},{"title":"«Він не такий розумний, як Майк»","bad":"Jack is not as clever than Mike.","good":"Jack is not as clever <b>as</b> Mike.","goodPlain":"Jack is not as clever as Mike.","rule":"Після <i>as + прикметник</i> другий елемент — <b>as</b>, а не than."},{"title":"«Я старший за вас на два роки»","bad":"I'm older than you two years.","good":"I'm <b>two years</b> older than you.","goodPlain":"I'm two years older than you.","rule":"На скільки — ставимо перед comparative: <i>two years older</i>, <i>three inches shorter</i>."},{"title":"«Ця машина вдвічі дорожча»","bad":"This car is twice more expensive than that one.","good":"This car is twice <b>as expensive as</b> that one.","goodPlain":"This car is twice as expensive as that one.","rule":"Кратність: <i>twice as … as</i>. Не <s>twice more … than</s>."},{"title":"«Ніл — найдовша річка»","bad":"The Nile is the more longer river in the world.","good":"The Nile is the <b>longest</b> river in the world.","goodPlain":"The Nile is the longest river in the world.","rule":"Один склад: просто <i>-est</i>. Не поєднуємо more з -er."},{"title":"«Він кращий студент, ніж його сестра»","bad":"Tom is a better student from his sister.","good":"Tom is a better student <b>than</b> his sister.","goodPlain":"Tom is a better student than his sister.","rule":"Порівняльне «ніж» — завжди <b>than</b>, не from."},{"title":"«Найвища гора світу»","bad":"Mount Everest is the highest mountain of the world.","good":"Mount Everest is the highest mountain <b>in</b> the world.","goodPlain":"Mount Everest is the highest mountain in the world.","rule":"Місце → <b>in</b>: <i>in the world, in our town, in the class</i>."},{"title":"«Їхній будинок такий сучасний, як наш»","bad":"Their house is modern as ours.","good":"Their house is <b>as modern as</b> ours.","goodPlain":"Their house is as modern as ours.","rule":"Потрібні два <i>as</i>: перед прикметником і після нього."},{"title":"«Моя сестра старша за мене на п'ять років»","bad":"My sister is five years elder than me.","good":"My sister is five years <b>older</b> than me.","goodPlain":"My sister is five years older than me.","rule":"<i>Elder</i> лише перед іменником і не вживається з than."}]}$g61$::jsonb, null, 9
