insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g63$th_10$g63$, $g64$Стоп-калька: прислівники, like / as, quite$g64$, $g65$intermediate$g65$, $g66$traps$g66$, $g67${"step":"Стоп-калька 2","kicker":"Ще дев'ять пасток","lead":"Помилки з прислівниками, словами like й as та підсилювачами.","items":[{"title":"«Тато наполегливо працює»","bad":"Dad works hardly.","good":"Dad works <b>hard</b>.","goodPlain":"Dad works hard.","rule":"<i>Hardly</i> = ледве. «Наполегливо» — <i>hard</i>."},{"title":"«Він говорив зліше, ніж завжди»","bad":"He spoke to me angrier than usual.","good":"He spoke to me <b>more angrily</b> than usual.","goodPlain":"He spoke to me more angrily than usual.","rule":"Прислівник на <i>-ly</i> утворює порівняння через <b>more</b>."},{"title":"«Дівчинка виглядала як ангел»","bad":"The little girl looked as an angel.","good":"The little girl looked <b>like</b> an angel.","goodPlain":"The little girl looked like an angel.","rule":"Після <i>look, feel, smell, sound, taste</i> + іменник — <b>like</b>."},{"title":"«Він привітно усміхнувся»","bad":"He smiled friendly.","good":"He smiled <b>in a friendly way</b>.","goodPlain":"He smiled in a friendly way.","rule":"<i>Friendly</i> закінчується на -ly, але це прикметник. Прислівника <s>friendlily</s> немає, тому: <i>in a friendly way</i>."},{"title":"«Сьогодні надзвичайно холодно»","bad":"It is cold extremely today.","good":"It is <b>extremely cold</b> today.","goodPlain":"It is extremely cold today.","rule":"Підсилювач стоїть <b>перед</b> прикметником."},{"title":"«Якщо вам потрібна додаткова інформація»","bad":"Call me if you need farther information.","good":"Call me if you need <b>further</b> information.","goodPlain":"Call me if you need further information.","rule":"«Додатковий» = <i>further</i>. <i>Farther</i> лише про відстань."},{"title":"«Він доволі високий чоловік»","bad":"He is a quite tall man.","good":"He is <b>quite a</b> tall man.","goodPlain":"He is quite a tall man.","rule":"<i>Quite</i> стоїть перед <i>a / an</i>, а не після нього."},{"title":"«Нова софа трохи більша»","bad":"The new sofa is quite bigger than the old one.","good":"The new sofa is <b>rather</b> bigger than the old one.","goodPlain":"The new sofa is rather bigger than the old one.","rule":"З comparative вживаємо <i>rather</i>, а не quite."},{"title":"«Кава досить міцна»","bad":"The coffee is quite strong to drink.","good":"The coffee is quite strong.","goodPlain":"The coffee is quite strong.","rule":"Після прикметника <i>to drink</i> не додаємо."}]}$g67$::jsonb, null, 10
from public.topics where slug = $g68$comparisons$g68$
on conflict (topic_id, block_key) do update set
  title = excluded.title, level = excluded.level, kind = excluded.kind,
  content_json = excluded.content_json, content_html = excluded.content_html, position = excluded.position;

