  ($g69$cmp_ex18_1$g69$, $g70$choice$g70$, $g71$intermediate$g71$, $g72${"id":"cmp_ex18_1","level":"intermediate","group":18,"instruction":"Fill in the gaps with like or as.","before":"Yes. No one else can paint","options":["like","as"],"after":"her.","correct":"like","explanation":"Like + займенник: схожість («так, як вона»)."}$g72$, 0),
  ($g73$cmp_ex18_2$g73$, $g74$choice$g74$, $g75$intermediate$g75$, $g76${"id":"cmp_ex18_2","level":"intermediate","group":18,"instruction":"Fill in the gaps with like or as.","before":"I agree. She acts","options":["like","as"],"after":"a child sometimes.","correct":"like","explanation":"Like + іменник: схожість, «поводиться, як дитина»."}$g76$, 1),
  ($g77$cmp_ex18_3$g77$, $g78$choice$g78$, $g79$intermediate$g79$, $g80${"id":"cmp_ex18_3","level":"intermediate","group":18,"instruction":"Fill in the gaps with like or as.","before":"Do it","options":["like","as"],"after":"we taught you.","correct":"as","explanation":"As + підмет + дієслово: «так, як». Спосіб дії."}$g80$, 2),
  ($g81$cmp_ex18_4$g81$, $g82$choice$g82$, $g83$intermediate$g83$, $g84${"id":"cmp_ex18_4","level":"intermediate","group":18,"instruction":"Fill in the gaps with like or as.","before":"Yes. The lead actor was wonderful","options":["like","as"],"after":"Macbeth.","correct":"as","explanation":"As = в ролі: актор у ролі Макбета."}$g84$, 3),
  ($g85$cmp_ex18_5$g85$, $g86$choice$g86$, $g87$intermediate$g87$, $g88${"id":"cmp_ex18_5","level":"intermediate","group":18,"instruction":"Fill in the gaps with like or as.","before":"He works","options":["like","as"],"after":"a hotel manager.","correct":"as","explanation":"As називає професію чи роль."}$g88$, 4),
  ($g89$cmp_ex18_6$g89$, $g90$choice$g90$, $g91$intermediate$g91$, $g92${"id":"cmp_ex18_6","level":"intermediate","group":18,"instruction":"Fill in the gaps with like or as.","before":"I'm not sure. It tastes","options":["like","as"],"after":"beef.","correct":"like","explanation":"Після taste + іменник — like."}$g92$, 5),
  ($g93$cmp_ex18_7$g93$, $g94$choice$g94$, $g95$intermediate$g95$, $g96${"id":"cmp_ex18_7","level":"intermediate","group":18,"instruction":"Fill in the gaps with like or as.","before":"Gosh! It's exactly the same","options":["like","as"],"after":"the one I bought!","correct":"as","explanation":"The same … as: стала конструкція."}$g96$, 6),
  ($g97$cmp_ex18_8$g97$, $g98$choice$g98$, $g99$intermediate$g99$, $g100${"id":"cmp_ex18_8","level":"intermediate","group":18,"instruction":"Fill in the gaps with like or as.","before":"Me too. He looks","options":["like","as"],"after":"my old maths teacher.","correct":"like","explanation":"Після look + іменник — like."}$g100$, 7),
  ($g101$cmp_ex18_9$g101$, $g102$choice$g102$, $g103$intermediate$g103$, $g104${"id":"cmp_ex18_9","level":"intermediate","group":18,"instruction":"Fill in the gaps with like or as.","before":"I know. It was","options":["like","as"],"after":"being in an oven.","correct":"like","explanation":"Like + -ing: порівняння."}$g104$, 8),
  ($g105$cmp_ex18_10$g105$, $g106$choice$g106$, $g107$intermediate$g107$, $g108${"id":"cmp_ex18_10","level":"intermediate","group":18,"instruction":"Fill in the gaps with like or as.","before":"Yes. He is known","options":["like","as"],"after":"one of the greatest rock musicians of our time.","correct":"as","explanation":"Be known + as: вважається, відомий як."}$g108$, 9),
  ($g109$cmp_ex18_11$g109$, $g110$choice$g110$, $g111$intermediate$g111$, $g112${"id":"cmp_ex18_11","level":"intermediate","group":18,"instruction":"Fill in the gaps with like or as.","before":"I don't know. It smells","options":["like","as"],"after":"fish.","correct":"like","explanation":"Після smell + іменник — like."}$g112$, 10),
  ($g113$cmp_ex12_1$g113$, $g114$gap$g114$, $g115$elementary$g115$, $g116${"id":"cmp_ex12_1","level":"elementary","group":12,"instruction":"Put the adjectives in brackets into the comparative or superlative form, adding any necessary words.","prompt":"Yes. It was ______ (funny) film I've ever seen.","answers":["the funniest"],"explanation":"Після «I've ever seen» потрібен superlative: the funniest. У прикметників на -y: y → i + est."}$g116$, 0),
  ($g117$cmp_ex12_2$g117$, $g118$gap$g118$, $g119$elementary$g119$, $g120${"id":"cmp_ex12_2","level":"elementary","group":12,"instruction":"Put the adjectives in brackets into the comparative or superlative form, adding any necessary words.","prompt":"Yes. He's ______ (tall) boy in our class.","answers":["the tallest"],"explanation":"Один із групи — superlative: the tallest."}$g120$, 1),
  ($g121$cmp_ex12_3$g121$, $g122$gap$g122$, $g123$elementary$g123$, $g124${"id":"cmp_ex12_3","level":"elementary","group":12,"instruction":"Put the adjectives in brackets into the comparative or superlative form, adding any necessary words.","prompt":"Yes. I left far ______ (late) I had intended to.","answers":["later than"],"explanation":"Порівняння двох моментів: comparative + than. Far підсилює comparative."}$g124$, 2),
  ($g125$cmp_ex12_4$g125$, $g126$gap$g126$, $g127$elementary$g127$, $g128${"id":"cmp_ex12_4","level":"elementary","group":12,"instruction":"Put the adjectives in brackets into the comparative or superlative form, adding any necessary words.","prompt":"Yes, but it was far ______ (expensive) the blue one.","answers":["more expensive than"],"explanation":"Довгий прикметник: more + than. Far підсилює comparative."}$g128$, 3),
  ($g129$cmp_ex12_5$g129$, $g130$gap$g130$, $g131$elementary$g131$, $g132${"id":"cmp_ex12_5","level":"elementary","group":12,"instruction":"Put the adjectives in brackets into the comparative or superlative form, adding any necessary words.","prompt":"Because it's much ______ (warm) England.","answers":["warmer than"],"explanation":"Один склад: -er + than. Much підсилює comparative."}$g132$, 4),
  ($g133$cmp_ex12_6$g133$, $g134$gap$g134$, $g135$elementary$g135$, $g136${"id":"cmp_ex12_6","level":"elementary","group":12,"instruction":"Put the adjectives in brackets into the comparative or superlative form, adding any necessary words.","prompt":"Oh, yes. It's ______ (good) job I've ever had.","answers":["the best"],"explanation":"Після «I've ever had» — superlative. Good → best (неправильна форма)."}$g136$, 5),
  ($g137$cmp_ex12_7$g137$, $g138$gap$g138$, $g139$elementary$g139$, $g140${"id":"cmp_ex12_7","level":"elementary","group":12,"instruction":"Put the adjectives in brackets into the comparative or superlative form, adding any necessary words.","prompt":"Thank you. That's very kind of you. — If you need any ______ (far) help, just ask me.","answers":["further"],"explanation":"Further help = додаткова допомога. У значенні «додатковий» — лише further."}$g140$, 6),
  ($g141$cmp_ex12_8$g141$, $g142$gap$g142$, $g143$elementary$g143$, $g144${"id":"cmp_ex12_8","level":"elementary","group":12,"instruction":"Put the adjectives in brackets into the comparative or superlative form, adding any necessary words.","prompt":"Yes. She's ______ (intelligent) woman I've ever met.","answers":["the most intelligent"],"explanation":"Три склади й більше: the most + «I've ever met»."}$g144$, 7),
  ($g145$cmp_ex12_9$g145$, $g146$gap$g146$, $g147$elementary$g147$, $g148${"id":"cmp_ex12_9","level":"elementary","group":12,"instruction":"Put the adjectives in brackets into the comparative or superlative form, adding any necessary words.","prompt":"I know. They were enormous. — Dinosaurs were ______ (big) houses.","answers":["bigger than"],"explanation":"Подвоєння приголосної: big → bigger. Then than."}$g148$, 8),
  ($g149$cmp_ex12_10$g149$, $g150$gap$g150$, $g151$elementary$g151$, $g152${"id":"cmp_ex12_10","level":"elementary","group":12,"instruction":"Put the adjectives in brackets into the comparative or superlative form, adding any necessary words.","prompt":"£5. It was ______ (cheap) one I could find.","answers":["the cheapest"],"explanation":"Із групи (one I could find) — superlative: the cheapest."}$g152$, 9),
  ($g153$cmp_ex12_11$g153$, $g154$gap$g154$, $g155$elementary$g155$, $g156${"id":"cmp_ex12_11","level":"elementary","group":12,"instruction":"Put the adjectives in brackets into the comparative or superlative form, adding any necessary words.","prompt":"I agree. It was a lot ______ (difficult) I had expected.","answers":["more difficult than"],"explanation":"A lot підсилює comparative: more difficult than."}$g156$, 10),
  ($g157$cmp_ex12_12$g157$, $g158$gap$g158$, $g159$elementary$g159$, $g160${"id":"cmp_ex12_12","level":"elementary","group":12,"instruction":"Put the adjectives in brackets into the comparative or superlative form, adding any necessary words.","prompt":"Yes, but he doesn't seem to be getting ______ (good).","answers":["any better"],"explanation":"Any + comparative вживаємо в запереченнях: any better."}$g160$, 11),
  ($g161$cmp_ex13_1$g161$, $g162$gap$g162$, $g163$elementary$g163$, $g164${"id":"cmp_ex13_1","level":"elementary","group":13,"instruction":"Fill in the gaps with the correct form of the adjective/adverb in brackets.","prompt":"I like living in the country. It's a lot ______ (peaceful) than the city.","answers":["more peaceful"],"explanation":"A lot + comparative. Peaceful — довге слово: more peaceful."}$g164$, 12),
  ($g165$cmp_ex13_2$g165$, $g166$gap$g166$, $g167$elementary$g167$, $g168${"id":"cmp_ex13_2","level":"elementary","group":13,"instruction":"Fill in the gaps with the correct form of the adjective/adverb in brackets.","prompt":"I felt very ill last week, but I'm slightly ______ (good) now.","answers":["better"],"explanation":"Slightly + comparative. Good → better."}$g168$, 13),
