  ($g173$cmp_ex13_4$g173$, $g174$gap$g174$, $g175$elementary$g175$, $g176${"id":"cmp_ex13_4","level":"elementary","group":13,"instruction":"Fill in the gaps with the correct form of the adjective/adverb in brackets.","prompt":"Steven is ______ (tall) boy in the basketball team.","answers":["the tallest"],"explanation":"Один із групи — the tallest."}$g176$, 15),
  ($g177$cmp_ex13_5$g177$, $g178$gap$g178$, $g179$elementary$g179$, $g180${"id":"cmp_ex13_5","level":"elementary","group":13,"instruction":"Fill in the gaps with the correct form of the adjective/adverb in brackets.","prompt":"This computer is very old. I need something ______ (modern).","answers":["more modern"],"explanation":"Порівняння з теперішнім: more modern."}$g180$, 16),
  ($g181$cmp_ex13_6$g181$, $g182$gap$g182$, $g183$elementary$g183$, $g184${"id":"cmp_ex13_6","level":"elementary","group":13,"instruction":"Fill in the gaps with the correct form of the adjective/adverb in brackets.","prompt":"The new library is far ______ (close) to my house than the old one.","answers":["closer"],"explanation":"Far + comparative: closer (than the old one)."}$g184$, 17),
  ($g185$cmp_ex13_7$g185$, $g186$gap$g186$, $g187$elementary$g187$, $g188${"id":"cmp_ex13_7","level":"elementary","group":13,"instruction":"Fill in the gaps with the correct form of the adjective/adverb in brackets.","prompt":"Jane's new haircut makes her look much ______ (attractive).","answers":["more attractive"],"explanation":"Much + comparative: more attractive."}$g188$, 18),
  ($g189$cmp_ex13_8$g189$, $g190$gap$g190$, $g191$elementary$g191$, $g192${"id":"cmp_ex13_8","level":"elementary","group":13,"instruction":"Fill in the gaps with the correct form of the adjective/adverb in brackets.","prompt":"This jacket was by far ______ (expensive) in the shop.","answers":["the most expensive"],"explanation":"By far вживаємо з superlative: the most expensive."}$g192$, 19),
