  ($g253$cmp_ex15_4$g253$, $g254$gap$g254$, $g255$intermediate$g255$, $g256${"id":"cmp_ex15_4","level":"intermediate","group":15,"instruction":"Write the correct form of the comparative or superlative and complete the sentences with your own ideas.","prompt":"I can swim well, but I can dance even ______ (good).","answers":["better"],"explanation":"Even + comparative. Well / good → better."}$g256$, 35),
  ($g257$cmp_ex15_5$g257$, $g258$gap$g258$, $g259$intermediate$g259$, $g260${"id":"cmp_ex15_5","level":"intermediate","group":15,"instruction":"Write the correct form of the comparative or superlative and complete the sentences with your own ideas.","prompt":"I think physics is ______ (difficult) subject of all.","answers":["the most difficult"],"explanation":"Of all → the most difficult."}$g260$, 36),
  ($g261$cmp_ex15_6$g261$, $g262$gap$g262$, $g263$intermediate$g263$, $g264${"id":"cmp_ex15_6","level":"intermediate","group":15,"instruction":"Write the correct form of the comparative or superlative and complete the sentences with your own ideas.","prompt":"Diamonds are ______ (valuable) rubies.","answers":["more valuable than"],"explanation":"Довге слово: more valuable than."}$g264$, 37),
  ($g265$cmp_ex15_7$g265$, $g266$gap$g266$, $g267$intermediate$g267$, $g268${"id":"cmp_ex15_7","level":"intermediate","group":15,"instruction":"Write the correct form of the comparative or superlative and complete the sentences with your own ideas.","prompt":"Fruit is ______ (healthy) food of all.","answers":["the healthiest"],"explanation":"Healthy → the healthiest (y → i). Of all."}$g268$, 38),
