  ($g497$cmp_ex19_12$g497$, $g498$abcd$g498$, $g499$advanced$g499$, $g500${"id":"cmp_ex19_12","level":"advanced","group":19,"instruction":"Correct the mistakes.","q":"12. Яке речення правильне? «His flat is big as mine.»","options":["A) His flat is big as mine.","B) His flat is as big as mine.","C) His flat is as big than mine.","D) His flat is so big like mine."],"correct":1,"explanation":"As + прикметник + as."}$g500$, 11),
  ($g501$cmp_ex19_13$g501$, $g502$abcd$g502$, $g503$advanced$g503$, $g504${"id":"cmp_ex19_13","level":"advanced","group":19,"instruction":"Correct the mistakes.","q":"13. Яке речення правильне? «Her new car is quite faster than her old one.»","options":["A) Her new car is quite faster than her old one.","B) Her new car is very faster than her old one.","C) Her new car is rather faster than her old one.","D) Her new car is more faster than her old one."],"correct":2,"explanation":"З comparative: rather (або much, far, a lot), не quite."}$g504$, 12),
  ($g505$cmp_ex19_14$g505$, $g506$abcd$g506$, $g507$advanced$g507$, $g508${"id":"cmp_ex19_14","level":"advanced","group":19,"instruction":"Correct the mistakes.","q":"14. Яке речення правильне? «This cake is quite sweet to eat.»","options":["A) This cake is quite sweet.","B) This cake is quite sweet to eat.","C) This cake is quite to eat sweet.","D) This cake is quite sweetly."],"correct":0,"explanation":"Після прикметника to eat не потрібне."}$g508$, 13),
  ($g509$cmp_ex19_15$g509$, $g510$abcd$g510$, $g511$advanced$g511$, $g512${"id":"cmp_ex19_15","level":"advanced","group":19,"instruction":"Correct the mistakes.","q":"15. Яке речення правильне? «The green dress is twice cheaper than the black one.»","options":["A) The green dress is twice cheaper than the black one.","B) The green dress is twice more cheap than the black one.","C) The green dress is twice as cheap as the black one.","D) The green dress is twice as cheaper as the black one."],"correct":2,"explanation":"Кратність: twice as + прикметник + as."}$g512$, 14),
  ($g513$cmp_ex19_16$g513$, $g514$abcd$g514$, $g515$advanced$g515$, $g516${"id":"cmp_ex19_16","level":"advanced","group":19,"instruction":"Correct the mistakes.","q":"16. Яке речення правильне? «I feel ill very today.»","options":["A) I feel very ill today.","B) I feel ill very today.","C) I feel illy today.","D) I very feel ill today."],"correct":0,"explanation":"Підсилювач перед прикметником: very ill."}$g516$, 15),
  ($g517$cmp_ex19_17$g517$, $g518$abcd$g518$, $g519$advanced$g519$, $g520${"id":"cmp_ex19_17","level":"advanced","group":19,"instruction":"Correct the mistakes.","q":"17. Яке речення правильне? «She laughed happy.»","options":["A) She laughed happy.","B) She laughed happily.","C) She laughed happier.","D) She laughed in a happy."],"correct":1,"explanation":"Після дієслова — прислівник: happily."}$g520$, 16)
) as v(lid, type, level, payload, pos)
on conflict (legacy_id) where student_id is null do update set
  topic_id = excluded.topic_id, type = excluded.type, level = excluded.level,
  payload = excluded.payload, position = excluded.position;

commit;

-- Контроль: блоки теорії за рівнями та кількість вправ за типами
select 'теорія' as що, tb.level as деталь, count(*) from public.theory_blocks tb join public.topics t on t.id = tb.topic_id
  where t.slug = $g523$comparisons$g523$ group by tb.level
union all
select 'вправи', e.type, count(*) from public.exercises e join public.topics t on t.id = e.topic_id
  where t.slug = $g524$comparisons$g524$ and e.student_id is null group by e.type order by 1, 2;
